```zig
const std = @import("std");
const mem = std.mem;

pub const ChangeError = error{
    NegativeTarget,
    UnreachableTarget,
};

pub fn findFewestCoins(
    allocator: mem.Allocator,
    coins: []const u64,
    target: i64,
) (mem.Allocator.Error || ChangeError)![]u64 {
    if (target < 0) {
        return error.NegativeTarget;
    }
    const t = @as(usize, @intCast(target));
    if (t == 0) {
        // Return empty slice for zero target.
        return allocator.alloc(u64, 0);
    }

    // DP arrays.
    var dp: []usize = try allocator.alloc(usize, t + 1);
    defer allocator.free(dp);
    var prev: []u64 = try allocator.alloc(u64, t + 1);
    defer allocator.free(prev);

    // Initialize dp with a large value (unreachable).
    const INF = std.math.maxInt(usize);
    for (dp) |*val| {
        val.* = INF;
    }
    mem.set(u64, prev, 0);
    dp[0] = 0;

    // Fill DP table.
    for (1..t + 1) |i| {
        for (coins) |coin| {
            const coin_usize = @as(usize, coin);
            if (coin_usize > i) continue;
            const prev_count = dp[i - coin_usize];
            if (prev_count + 1 < dp[i]) {
                dp[i] = prev_count + 1;
                prev[i] = coin;
            }
        }
    }

    if (dp[t] == INF) {
        return error.UnreachableTarget;
    }

    const count = dp[t];
    var res = try allocator.alloc(u64, count);
    errdefer allocator.free(res);

    // Reconstruct coins in reverse order.
    var remaining = t;
    for (0..count) |idx| {
        const i = count - 1 - idx;
        const coin = prev[remaining];
        res[i] = coin;
        remaining -= coin;
    }

    // Sort ascending to match test expectations.
    std.sort.asc(u64, res, {});

    return res;
}
```

